package com.ebuddy.j2me;
import javax.microedition.lcdui.*;
public final class LoginForm extends Form implements CommandListener { final EbuddyMidlet app; final TextField user=new TextField("User","",32,TextField.ANY); final TextField pass=new TextField("Password","",32,TextField.PASSWORD); final Command login=new Command("Login",Command.OK,1); final Command reg=new Command("Register",Command.SCREEN,2); final Command exit=new Command("Exit",Command.EXIT,9); public LoginForm(EbuddyMidlet a){super("eBuddy Login");app=a;append(user);append(pass);addCommand(login);addCommand(reg);addCommand(exit);setCommandListener(this);} public void setBusy(boolean b){} public void fail(String s){setBusy(false);Alert x=new Alert("Login",s,null,AlertType.ERROR);x.setTimeout(2000);app.display.setCurrent(x,this);} public void commandAction(Command c,Displayable d){if(c==login)app.login(user.getString(),pass.getString());else if(c==reg)app.showRegister();else if(c==exit)app.notifyDestroyed();}}
